// Append the generated-artefact ignore rule without going through a shell
// redirection, which the repository policy scanner rejects as a path escape.
import { appendFileSync } from "node:fs";

appendFileSync(
  ".gitignore",
  [
    "",
    "# Generated by `npm run archify` (depcruise). A ~200KB artefact that changes on",
    "# every dependency edit, so the CONFIG is tracked and the OUTPUT is not.",
    "architecture.html",
    "",
  ].join("\n"),
);
console.log("gitignore updated");